// This file is generated by AI.

// 框架无关的多步会话状态机: 输入 → 处理 → 分配说话者 → 导出。
// 通过注入的 IEditorHost 与编辑器交互, 不依赖 Monaco / React, 可无头测试。

import { parse, serialize, toWebGALScript, type Diagnostic, type DocumentModel, type Speaker } from './model';
import { preprocess, type Warning } from './pipeline';

/** 编辑器抽象: 宿主 (Monaco / CodeMirror / 自绘) 实现此接口。 */
export interface IEditorHost {
  getContent(): string;
  setContent(text: string): void;
  setReadOnly(readOnly: boolean): void;
  /** 替换 0 基指定行的整行内容 (不重置光标)。 */
  replaceLine(line: number, text: string): void;
  /** 选中 0 基 [start, end] 整行 (含两端)。 */
  selectLines(start: number, end: number): void;
  setCursorLine(line: number): void;
  onContentChange(cb: (text: string) => void): () => void;
  onCursorLine(cb: (line: number) => void): () => void;
  /** 返回 true 表示已消费该按键。 */
  onKey(cb: (key: string) => boolean): () => void;
  focus(): void;
}

export type Step = 1 | 2 | 3 | 4;

export interface SessionState {
  step: Step;
  /** 当前步骤对应的编辑器文本。 */
  text: string;
  speakers: Speaker[];
  warnings: Warning[];
  diagnostics: Diagnostic[];
  /** 未分配说话者的对话段数量。 */
  unresolvedCount: number;
  /** 是否等待用户确认「未分配按旁白处理」。 */
  pendingConfirm: boolean;
  canGoBack: boolean;
  canGoNext: boolean;
  /** 当前选中对话段的段首行 (0 基, -1 表示无)。 */
  selectedHeadLine: number;
}

const MAX_SPEAKERS = 35;
export const SPEAKER_KEYS = [...'123456789', ...'ABCDEFGHIJKLMNOPQRSTUVWXYZ'];

export class NovelSession {
  private host: IEditorHost | null = null;
  private step: Step = 1;
  private texts: Record<Step, string> = { 1: '', 2: '', 3: '', 4: '' };
  private model: DocumentModel | null = null;
  private speakers: Speaker[] = [];
  private warnings: Warning[] = [];
  private diagnostics: Diagnostic[] = [];
  private pendingConfirm = false;
  private currentSegment = -1;
  /** 最近一次光标行 (0 基), 用于「未选中时锁定到向下最近的对话段」。 */
  private lastCursorLine = 0;
  private listeners = new Set<() => void>();
  private unsubs: Array<() => void> = [];
  private snapshot: SessionState;

  constructor(host: IEditorHost) {
    this.texts[1] = host.getContent();
    this.attach(host);
    this.snapshot = this.computeSnapshot();
  }

  /** 绑定 (或换绑) 编辑器宿主: 重建订阅并恢复编辑器到当前步骤状态。 */
  attach(host: IEditorHost): void {
    if (this.host === host) return;
    this.detach();
    this.host = host;

    this.unsubs.push(
      host.onContentChange((text) => {
        if (this.step === 1 || this.step === 2) this.texts[this.step] = text;
        // 第 2 步实时解析诊断 (供 Monaco markers 显示)
        if (this.step === 2) this.diagnostics = parse(text).diagnostics;
        this.emit();
      }),
      host.onCursorLine((line) => this.onCursorLine(line)),
      host.onKey((key) => this.onKey(key))
    );

    // 恢复编辑器到当前步骤状态。
    host.setReadOnly(this.step === 3 || this.step === 4);
    host.setContent(this.texts[this.step]);
    if (this.step === 3) {
      host.focus();
      if (this.currentSegment >= 0 && this.model) {
        const seg = this.model.segments[this.currentSegment];
        if (seg) host.selectLines(seg.lines[0], seg.lines[seg.lines.length - 1]);
      }
    }
  }

  /** 解绑宿主 (保留会话状态, 供选项卡切换后重新绑定)。 */
  detach(): void {
    this.unsubs.forEach((u) => u());
    this.unsubs = [];
    this.host = null;
  }

  /** 彻底销毁 (解绑并清除监听)。 */
  dispose(): void {
    this.detach();
    this.listeners.clear();
  }

  subscribe(listener: () => void): () => void {
    this.listeners.add(listener);
    return () => {
      this.listeners.delete(listener);
    };
  }

  getState(): SessionState {
    return this.snapshot;
  }

  // -------- 内部 --------

  private computeSnapshot(): SessionState {
    const unresolved = this.model?.segments.filter((s) => s.speaker === null).length ?? 0;
    const seg = this.currentSegment >= 0 && this.model ? this.model.segments[this.currentSegment] : undefined;
    return {
      step: this.step,
      text: this.texts[this.step],
      speakers: this.speakers,
      warnings: this.warnings,
      diagnostics: this.diagnostics,
      unresolvedCount: unresolved,
      pendingConfirm: this.pendingConfirm,
      canGoBack: this.step > 1,
      canGoNext: this.canNext(),
      selectedHeadLine: seg?.head ?? -1,
    };
  }

  private emit(): void {
    this.snapshot = this.computeSnapshot();
    this.listeners.forEach((l) => l());
  }

  private canNext(): boolean {
    if (this.pendingConfirm) return false;
    switch (this.step) {
      case 1:
        return this.texts[1].trim() !== '';
      case 2:
      case 3:
        return true;
      case 4:
        return false;
    }
  }

  private syncHost(): void {
    const host = this.host;
    if (!host) return;
    host.setReadOnly(this.step === 3 || this.step === 4);
    host.setContent(this.texts[this.step]);
    if (this.step === 3) {
      host.focus();
      if (this.currentSegment >= 0 && this.model) {
        const seg = this.model.segments[this.currentSegment];
        if (seg) host.selectLines(seg.lines[0], seg.lines[seg.lines.length - 1]);
      }
    }
  }

  private generate(): void {
    if (!this.model) return;
    this.texts[4] = toWebGALScript(this.model, { speakers: this.speakers });
    this.step = 4;
    this.currentSegment = -1;
    this.syncHost();
  }

  // -------- 步骤流转 --------

  next(): void {
    switch (this.step) {
      case 1: {
        const { intermediate, warnings } = preprocess(this.texts[1]);
        this.warnings = warnings;
        this.texts[2] = intermediate;
        this.diagnostics = [];
        this.step = 2;
        this.syncHost();
        break;
      }
      case 2: {
        const { model, diagnostics } = parse(this.texts[2]);
        if (model.lines.length === 0) {
          diagnostics.push({ line: 0, severity: 'error', message: '中间文本为空, 无法继续' });
        }
        this.diagnostics = diagnostics;
        if (model.lines.length === 0) break;
        this.model = model;
        this.texts[3] = serialize(model);
        this.step = 3;
        // 进入分配步骤立即锁定第一个对话段 (无对话段则为 -1)。
        this.currentSegment = this.model.segments.length > 0 ? 0 : -1;
        this.syncHost();
        break;
      }
      case 3: {
        if (this.hasUnassigned()) {
          this.pendingConfirm = true;
          break;
        }
        this.generate();
        break;
      }
      case 4:
        break;
    }
    this.emit();
  }

  back(): void {
    if (this.pendingConfirm) {
      this.pendingConfirm = false;
      this.emit();
      return;
    }
    switch (this.step) {
      case 2:
        this.step = 1;
        break;
      case 3:
        this.step = 2;
        break;
      case 4:
        this.step = 3;
        this.currentSegment = -1;
        break;
      default:
        this.emit();
        return;
    }
    this.syncHost();
    this.emit();
  }

  /** 响应「未分配对话」确认: asNarration=true 时按旁白导出, 否则留在分配步。 */
  resolveUnresolved(asNarration: boolean): void {
    if (this.step !== 3 || !this.pendingConfirm) return;
    this.pendingConfirm = false;
    if (asNarration) this.generate();
    this.emit();
  }

  hasUnassigned(): boolean {
    return this.model?.segments.some((s) => s.speaker === null) ?? false;
  }

  // -------- 说话者 --------

  addSpeaker(): Speaker | null {
    if (this.speakers.length >= MAX_SPEAKERS) return null;
    const speaker: Speaker = { key: SPEAKER_KEYS[this.speakers.length], name: '' };
    this.speakers = [...this.speakers, speaker];
    this.emit();
    return speaker;
  }

  updateSpeaker(key: string, patch: Partial<Omit<Speaker, 'key'>>): void {
    this.speakers = this.speakers.map((s) => (s.key === key ? { ...s, ...patch } : s));
    this.emit();
  }

  removeSpeaker(key: string): void {
    this.speakers = this.speakers.filter((s) => s.key !== key).map((s, idx) => ({ ...s, key: SPEAKER_KEYS[idx] }));
    this.emit();
  }

  // -------- 分配 (第 3 步) --------

  private onCursorLine(line: number): void {
    this.lastCursorLine = line;
    if (this.step !== 3 || !this.model) return;
    const idx = this.model.segments.findIndex((s) => s.lines.includes(line));
    if (idx < 0) {
      if (this.currentSegment !== -1) {
        this.currentSegment = -1;
        this.emit();
      }
      return;
    }
    if (idx !== this.currentSegment) {
      this.currentSegment = idx;
      const seg = this.model.segments[idx];
      this.host?.selectLines(seg.lines[0], seg.lines[seg.lines.length - 1]);
      this.emit();
    }
  }

  /** 光标不在对话段上时, 锁定到向下最近的对话段 (无则回到第一个)。 */
  private lockToNearestSegment(): boolean {
    if (!this.model || this.model.segments.length === 0) return false;
    const below = this.model.segments.filter((s) => s.head >= this.lastCursorLine);
    const target = below.length > 0 ? below[0] : this.model.segments[0];
    this.currentSegment = this.model.segments.indexOf(target);
    this.host?.selectLines(target.lines[0], target.lines[target.lines.length - 1]);
    return true;
  }

  private onKey(key: string): boolean {
    if (this.step !== 3) return false;
    const speaker = this.speakers.find((s) => s.key === key.toUpperCase());
    if (!speaker) return false;
    this.assignCurrent(speaker);
    return true;
  }

  private assignCurrent(speaker: Speaker): void {
    if (this.step !== 3 || !this.model) return;
    let seg = this.model.segments[this.currentSegment];
    if (!seg) {
      // 光标未选中对话段: 锁定到向下最近的对话段。
      if (!this.lockToNearestSegment()) return;
      seg = this.model.segments[this.currentSegment];
    }
    const display = `${speaker.key}-${speaker.name}`;
    seg.speaker = display;
    this.model.lines[seg.head].speaker = display;

    // 定向替换段首行前缀 (避免 setContent 重置光标导致跳回第一段)。
    this.host?.replaceLine(seg.head, `${display}:${this.model.lines[seg.head].text}`);
    this.texts[3] = serialize(this.model);

    const next = this.currentSegment + 1;
    if (next < this.model.segments.length) {
      this.currentSegment = next;
      const ns = this.model.segments[next];
      this.host?.selectLines(ns.lines[0], ns.lines[ns.lines.length - 1]);
    } else {
      this.currentSegment = -1;
    }
    this.emit();
  }
}
